use anyhow::{Result,ensure};
use std::path::PathBuf;
fn main()->Result<()>{let root=PathBuf::from(std::env::args().nth(1).unwrap());let mut starts=Vec::new();let mut accepted=Vec::new();let mut total=Vec::new();
 for i in 0..60{let t=1795564800+i*60;starts.push(t as f64);for center in [436e6,444e6]{let f=hdf5::File::open(root.join(t.to_string()).join(format!("{center:.0}/matched-step2us.h5")))?;ensure!(f.attr("receiver_center_hz")?.read_scalar::<f64>()?==center,"wrong channel");ensure!(f.attr("integration_start_utc_s")?.read_scalar::<f64>()?==t as f64,"start");ensure!(f.attr("integration_stop_utc_s")?.read_scalar::<f64>()?==t as f64+60.,"stop");ensure!(f.attr("range_step_us")?.read_scalar::<f64>()?==2.,"step");let n=f.attr("accepted_pulses")?.read_scalar::<u64>()?;let nt=f.attr("total_pulses")?.read_scalar::<u64>()?;ensure!(n>0&&n<=nt&&nt<=3001,"channel pulse count");accepted.push(n);total.push(nt);}}
 for i in 0..60{let t=1795564800+i*60;for(ch,center)in [436e6,444e6].into_iter().enumerate(){let d=hdf5::File::open(root.join(t.to_string()).join(format!("{center:.0}/diagnostic.h5")))?;let headers=d.dataset("raw_headers")?.read_raw::<u8>()?;ensure!(headers.len()==total[i*2+ch]as usize*1024,"raw ledger length");ensure!(headers.chunks_exact(1024).all(|h|430e6+h[34]as f64*0.2e6==center),"raw receiver mixing");}
 let d=hdf5::File::open(root.join(format!("movie/minute-{t}/display/profile-01-native.h5")))?;ensure!(d.attr("integration_start_utc_s")?.read_scalar::<f64>()?==t as f64,"wrong frame time");ensure!(d.attr("splice_rf_hz")?.read_scalar::<f64>()?==440e6,"wrong splice");let freq=d.dataset("frequency_hz")?.read_raw::<f64>()?;ensure!(freq.len()==12288&&freq[0]==428e6&&freq[12287]==452e6-1953.125&&freq.windows(2).all(|p|p[1]-p[0]==1953.125),"RF continuity");ensure!(d.dataset("accepted_pulses_per_channel")?.read_raw::<f64>()?==[accepted[i*2]as f64,accepted[i*2+1]as f64],"frame exposure mismatch");ensure!(root.join(format!("movie/frames/frame-{i:05}.png")).metadata()?.len()>0,"missing actual frame");}
 let out=hdf5::File::create(root.join("movie/frame-manifest.h5"))?;out.new_dataset::<f64>().shape(60).create("integration_start_utc_s")?.write_raw(&starts)?;out.new_dataset::<u64>().shape((60,2)).create("accepted_pulses")?.write_raw(&accepted)?;out.new_dataset::<u64>().shape((60,2)).create("total_pulses")?.write_raw(&total)?;out.new_dataset::<f64>().shape(2).create("receiver_center_hz")?.write_raw(&[436e6,444e6])?;for(name,v)in[("source_coverage_seconds",3600.),("splice_rf_hz",440e6),("transmit_frequency_hz",430e6),("range_step_us",2.)]{out.new_attr::<f64>().create(name)?.write_scalar(&v)?;}println!("PASS: 120 separate channel products; all retained raw receiver identities; 60 consecutive frame times and continuous RF axes; 3600 seconds of data");Ok(())}
